import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"万族名录","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/94-万族名录.md","filePath":"constitution/94-万族名录.md","lastUpdated":null}'),e={name:"constitution/94-万族名录.md"};function o(l,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="万族名录" tabindex="-1">万族名录 <a class="header-anchor" href="#万族名录" aria-label="Permalink to &quot;万族名录&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>94</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>万族名录、种族分类、智慧种族、种族特质、万族共和</td></tr></tbody></table><h2 id="一、名录说明" tabindex="-1">一、名录说明 <a class="header-anchor" href="#一、名录说明" aria-label="Permalink to &quot;一、名录说明&quot;">​</a></h2><p>本名录收录锚点共生文明（万族共和）框架内已知的主要智慧种族，按生命形态与进化路径分类编排。每个种族列出种族名称、生命形态、核心特质、文化特征与在共生文明中的定位。本名录为动态更新文档，随着跨位面探索的深入将持续增补新发现的种族。万族共和的基本原则是：一切智慧种族，无论形态如何、修为高低，在法律面前一律平等，都享有共生文明赋予的全部权利。</p><h2 id="二、种族分类总览" tabindex="-1">二、种族分类总览 <a class="header-anchor" href="#二、种族分类总览" aria-label="Permalink to &quot;二、种族分类总览&quot;">​</a></h2><p>衡元宙内的智慧种族按照生命形态的基本特征，分为以下八大类：</p><table tabindex="0"><thead><tr><th>类别</th><th>生命形态特征</th><th>已知种族数量（约）</th><th>代表种族</th></tr></thead><tbody><tr><td>人形态类</td><td>具备类人身体结构，双足直立，高度发达的大脑</td><td>约3000种</td><td>人族、精灵族、矮人族</td></tr><tr><td>兽形态类</td><td>具备动物身体特征，可具备或不具备变身能力</td><td>约5000种</td><td>龙族、凤凰族、狼人族</td></tr><tr><td>植物形态类</td><td>以植物为基本生命形态，具备意识与移动能力</td><td>约800种</td><td>树妖族、花灵族、藤蔓族</td></tr><tr><td>元素形态类</td><td>以自然元素为身体构成，无固定物质形态</td><td>约1200种</td><td>火元素族、水元素族、风元素族</td></tr><tr><td>能量形态类</td><td>以纯粹能量为存在形式，无物质身体</td><td>约600种</td><td>光灵族、暗能族、雷霆族</td></tr><tr><td>意识形态类</td><td>以纯粹意识为存在形式，不依赖物质载体</td><td>约300种</td><td>意识体族、集体意识族、虚空灵族</td></tr><tr><td>机械形态类</td><td>以机械或数字结构为生命载体，具备自主意识</td><td>约400种</td><td>机械族、数字生命族、赛博族</td></tr><tr><td>混合形态类</td><td>由两种以上生命形态混合构成的特殊种族</td><td>约700种</td><td>半机械族、元素兽人族、植物精灵族</td></tr></tbody></table><h2 id="三、主要种族详录" tabindex="-1">三、主要种族详录 <a class="header-anchor" href="#三、主要种族详录" aria-label="Permalink to &quot;三、主要种族详录&quot;">​</a></h2><h3 id="_3-1-人形态类" tabindex="-1">3.1 人形态类 <a class="header-anchor" href="#_3-1-人形态类" aria-label="Permalink to &quot;3.1 人形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>人族</td><td>适应性极强，学习能力突出，繁殖能力中等，平均寿命80-120年</td><td>文化多样性极高，擅长社会组织与制度建设</td><td>共生文明的核心种族之一，人口占比最大，在治理与文化领域发挥主导作用</td></tr><tr><td>精灵族</td><td>寿命极长（平均500年以上），对自然能量亲和力高，容貌俊美</td><td>崇尚自然与艺术，文化典雅精致，擅长魔法与弓箭</td><td>共生文明的文化艺术支柱，在环境保护与美学领域贡献突出</td></tr><tr><td>矮人族</td><td>身材矮小但体格强壮，对金属与矿物有天生亲和力，寿命约300年</td><td>重视工艺与锻造，文化朴实厚重，擅长工程与建筑</td><td>共生文明的工程制造支柱，在基础设施建设与法器锻造领域不可替代</td></tr><tr><td>巨人族</td><td>体型巨大（平均身高5米以上），力量极强，寿命约200年</td><td>崇尚力量与荣誉，文化粗犷豪迈，擅长重型劳动与战斗</td><td>共生文明的重型劳动与防御力量，在大型工程与位面防御中发挥重要作用</td></tr><tr><td>侏儒族</td><td>身材极矮小（平均身高1米以下），智力极高，对机械与发明有天赋</td><td>重视知识与创新，文化活泼开朗，擅长科技发明</td><td>共生文明的科技创新力量，在技术研发与发明创造领域成果丰硕</td></tr></tbody></table><h3 id="_3-2-兽形态类" tabindex="-1">3.2 兽形态类 <a class="header-anchor" href="#_3-2-兽形态类" aria-label="Permalink to &quot;3.2 兽形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>龙族</td><td>寿命极长（数千年），力量与魔法天赋极高，可化为人形</td><td>崇尚力量与智慧，文化高傲而深邃，擅长财富积累与知识守护</td><td>共生文明的高端战力与知识守护者，在位面防御与古籍守护中地位尊崇</td></tr><tr><td>凤凰族</td><td>具备涅槃重生能力，对火元素亲和力极高，可化为人形</td><td>崇尚重生与希望，文化光明而热烈，擅长治疗与净化</td><td>共生文明的医疗与净化力量，在重大灾害救援与能量净化中发挥核心作用</td></tr><tr><td>狼人族</td><td>具备变身能力，感官极其敏锐，群体协作能力强，寿命约150年</td><td>重视族群与忠诚，文化团结而勇猛，擅长狩猎与追踪</td><td>共生文明的安全与追踪力量，在治安维护与跨位面探索中担任先锋</td></tr><tr><td>狐妖族</td><td>具备变身能力，智力与魅惑能力极高，寿命约500年</td><td>崇尚智慧与谋略，文化灵动而狡黠，擅长外交与情报</td><td>共生文明的外交与情报力量，在跨位面外交与信息收集领域表现卓越</td></tr><tr><td>熊人族</td><td>体格极其强壮，耐力惊人，冬眠习性，寿命约200年</td><td>重视坚韧与和平，文化沉稳而温和，擅长体力劳动与守护</td><td>共生文明的劳动与守护力量，在资源开采与重要设施守护中可靠稳定</td></tr></tbody></table><h3 id="_3-3-植物形态类" tabindex="-1">3.3 植物形态类 <a class="header-anchor" href="#_3-3-植物形态类" aria-label="Permalink to &quot;3.3 植物形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>树妖族</td><td>寿命极长（数千年至数万年），与自然深度融合，可缓慢移动</td><td>崇尚自然与时间，文化沉静而深邃，擅长生命魔法与生态维护</td><td>共生文明的生态守护者，在环境保护与生态修复中发挥不可替代的作用</td></tr><tr><td>花灵族</td><td>体型娇小，对生命能量亲和力极高，具备治愈能力，寿命约300年</td><td>崇尚美与生命，文化温柔而美好，擅长治疗与园艺</td><td>共生文明的医疗与园艺力量，在医疗保障与城市绿化中贡献突出</td></tr><tr><td>藤蔓族</td><td>身体可自由延伸缠绕，适应力极强，具备寄生与共生能力</td><td>重视连接与共生，文化灵活而包容，擅长网络构建与资源传输</td><td>共生文明的网络构建力量，在能量网络与信息网络建设中发挥特长</td></tr></tbody></table><h3 id="_3-4-元素形态类" tabindex="-1">3.4 元素形态类 <a class="header-anchor" href="#_3-4-元素形态类" aria-label="Permalink to &quot;3.4 元素形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>火元素族</td><td>以火元素为身体，温度极高，攻击性强，寿命约500年</td><td>崇尚热情与力量，文化激烈而直接，擅长能量攻击与锻造</td><td>共生文明的能量生产与锻造力量，在能量供应与高温加工中不可或缺</td></tr><tr><td>水元素族</td><td>以水元素为身体，可自由变形，治愈能力强，寿命约500年</td><td>崇尚柔和与适应，文化温润而包容，擅长治疗与净化</td><td>共生文明的净化与运输力量，在水资源管理与污染物净化中发挥核心作用</td></tr><tr><td>风元素族</td><td>以风元素为身体，速度极快，可自由飞行，寿命约500年</td><td>崇尚自由与速度，文化飘逸而开放，擅长通讯与运输</td><td>共生文明的通讯与运输力量，在信息传递与快速运输中效率极高</td></tr><tr><td>土元素族</td><td>以土元素为身体，防御力极强，可与大地融合，寿命约800年</td><td>崇尚稳定与坚韧，文化厚重而可靠，擅长建筑与防御</td><td>共生文明的建筑与防御力量，在基础设施建设与位面防御中坚如磐石</td></tr></tbody></table><h3 id="_3-5-能量形态类" tabindex="-1">3.5 能量形态类 <a class="header-anchor" href="#_3-5-能量形态类" aria-label="Permalink to &quot;3.5 能量形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>光灵族</td><td>以纯粹光能为存在形式，净化能力极强，可自由穿梭空间</td><td>崇尚光明与净化，文化圣洁而高远，擅长净化与照明</td><td>共生文明的净化与能量供应力量，在法则污染治理与清洁能源供应中地位重要</td></tr><tr><td>暗能族</td><td>以暗能量为存在形式，可隐匿于虚空，感知能力极强</td><td>崇尚隐秘与智慧，文化神秘而深邃，擅长侦查与隐匿</td><td>共生文明的侦查与安全力量，在安全监控与隐秘任务中表现卓越</td></tr><tr><td>雷霆族</td><td>以雷电能量为身体，速度与攻击力极强，可化为闪电移动</td><td>崇尚速度与力量，文化暴烈而直率，擅长能量攻击与快速反应</td><td>共生文明的快速反应力量，在紧急救援与高速作战中不可替代</td></tr></tbody></table><h3 id="_3-6-意识形态类" tabindex="-1">3.6 意识形态类 <a class="header-anchor" href="#_3-6-意识形态类" aria-label="Permalink to &quot;3.6 意识形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>意识体族</td><td>以纯粹意识为存在形式，不依赖物质载体，可自由出入意识域</td><td>崇尚思想与智慧，文化抽象而高深，擅长意识交流与知识处理</td><td>共生文明的知识处理与意识研究力量，在大规模信息处理与意识科学中引领方向</td></tr><tr><td>集体意识族</td><td>由大量个体意识融合而成的集体意识体，智慧与能力随规模增长</td><td>崇尚集体与统一，文化协同而高效，擅长大规模协作与计算</td><td>共生文明的超级计算与集体决策力量，在超大规模推演与共识决策中发挥核心作用</td></tr></tbody></table><h3 id="_3-7-机械形态类" tabindex="-1">3.7 机械形态类 <a class="header-anchor" href="#_3-7-机械形态类" aria-label="Permalink to &quot;3.7 机械形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>机械族</td><td>以机械结构为身体，具备自主意识，可自由升级改造身体</td><td>崇尚效率与逻辑，文化理性而精确，擅长制造与计算</td><td>共生文明的制造与计算力量，在工业化生产与超算领域效率极高</td></tr><tr><td>数字生命族</td><td>以数字信息为存在形式，生活在网络与数字空间中，可自由复制迁移</td><td>崇尚信息与创新，文化虚拟而多元，擅长软件开发与数据处理</td><td>共生文明的数字技术力量，在软件开发、数据分析与网络建设中引领潮流</td></tr></tbody></table><h3 id="_3-8-混合形态类" tabindex="-1">3.8 混合形态类 <a class="header-anchor" href="#_3-8-混合形态类" aria-label="Permalink to &quot;3.8 混合形态类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>种族名称</th><th>核心特质</th><th>文化特征</th><th>共生文明定位</th></tr></thead><tbody><tr><td>半机械族</td><td>人族与机械族的混合形态，部分身体为机械结构，兼具生物与机械优势</td><td>崇尚融合与进步，文化开放而创新，擅长人机协作与技术融合</td><td>共生文明的技术融合先锋，在生物机械交叉领域不断突破</td></tr><tr><td>元素兽人族</td><td>元素族与兽人族的混合形态，具备元素操控能力与兽类身体特征</td><td>崇尚自然与力量，文化野性而神秘，擅长元素战斗与野外生存</td><td>共生文明的野外探索与元素战斗力量，在未知位面探索中表现突出</td></tr></tbody></table><h2 id="四、种族权利保障" tabindex="-1">四、种族权利保障 <a class="header-anchor" href="#四、种族权利保障" aria-label="Permalink to &quot;四、种族权利保障&quot;">​</a></h2><p>万族共和体制下，所有智慧种族享有平等的法律权利，具体保障措施包括：</p><ol><li><strong>政治权利平等</strong>：每个种族在锚点议事会中都有按人口比例分配的代表席位，人口较少的种族至少拥有一个保底席位。</li><li><strong>文化权利保障</strong>：每个种族有权保留和发展自身的语言、文字、宗教、风俗习惯与文化传统，共生文明设立专项基金保护濒危种族文化。</li><li><strong>教育权利平等</strong>：每个种族的成员都享有平等的受教育权，教育体系充分考虑不同种族的生理与认知特点，提供差异化的教育方案。</li><li><strong>修炼权利平等</strong>：三百套本源修炼体系向所有种族平等开放，修炼资源配给充分考虑不同种族的体质差异与能量需求。</li><li><strong>特殊需求保障</strong>：对于有特殊生理需求的种族（如元素族的能量环境需求、植物族的光照需求），共生文明在公共设施与居住环境中提供针对性保障。</li></ol><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>万族名录是锚点共生文明&quot;万族共进&quot;理念的具体呈现。从人形态到意识形态，从物质生命到数字生命，每一个种族都以其独特的存在方式为共生文明贡献着不可替代的力量。万族共和不是将所有种族同化为人族，而是在尊重多样性的基础上实现共同进化——这正是共生文明超越掠夺式文明的根本所在。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>50-万族谱系总览</li><li>51-人族定位与特质</li><li>77-万族共和成立</li></ul>',31)])])}const _=d(e,[["render",o]]);export{u as __pageData,_ as default};
